 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    candidates = []
    for color in set(v for row in grid for v in row):
        rows = [r for r, row in enumerate(grid) if row.count(color) >= 0.70 * w]
        cols = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= 0.70 * h]
        if len(rows) < 2 or len(cols) < 2:
            continue
        def regular(indices):
            gaps = [b-a for a,b in zip(indices,indices[1:])]
            return Counter(gaps).most_common(1)[0][1] / len(gaps) if gaps else 0
        candidates.append((regular(rows)+regular(cols), -(len(rows)+len(cols)), color, rows, cols))
    _, _, line, rows, cols = max(candidates, key=lambda item: (item[0], -len(item[3])-len(item[4])))
    bg = Counter(grid[r][c] for r in range(h) if r not in rows
                 for c in range(w) if c not in cols).most_common(1)[0][0]
    # Each marked divider intersection represents one lattice tile. A marker
    # propagates to its incident block(s); unmarked points leave the fill color.
    out = [[bg for _ in range(len(cols)-1)] for _ in range(len(rows)-1)]
    for i, r in enumerate(rows):
        for j, c in enumerate(cols):
            v = grid[r][c]
            if v == line:
                continue
            for oi in (i-1, i):
                for oj in (j-1, j):
                    if 0 <= oi < len(out) and 0 <= oj < len(out[0]):
                        out[oi][oj] = v
    return out
