def transform(grid):
    h, w = len(grid), len(grid[0])
    candidates=[]
    for color in set(v for row in grid for v in row):
        rs=[r for r,row in enumerate(grid) if row.count(color)>=.70*w]
        cs=[c for c in range(w) if sum(grid[r][c]==color for r in range(h))>=.70*h]
        if len(rs)<2 or len(cs)<2: continue
        def regular(xs):
            d=[b-a for a,b in zip(xs,xs[1:])]
            return Counter(d).most_common(1)[0][1]/len(d) if d else 0
        candidates.append((regular(rs)+regular(cs),-(len(rs)+len(cs)),color,rs,cs))
    _,_,line,rows,cols=max(candidates,key=lambda x:(x[0],-len(x[3])-len(x[4])))
    bg=Counter(grid[r][c] for r in range(h) if r not in rows for c in range(w) if c not in cols).most_common(1)[0][0]
    # Marked junctions propagate to incident tiles, but ordinary grid and fill
    # colors are not markers. Markers are colors distinct from both.
    all_colors=Counter(v for row in grid for v in row)
    marker_colors={v for v in all_colors if v not in (line,bg)}
    out=[[bg for _ in range(len(cols)-1)] for _ in range(len(rows)-1)]
    for i,r in enumerate(rows):
