 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    choices = []
    for color in set(v for row in grid for v in row):
        rows = [r for r, row in enumerate(grid) if row.count(color) >= .70 * w]
        cols = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= .70 * h]
        if len(rows) < 2 or len(cols) < 2:
            continue
        def regular(indices):
            gaps = [b-a for a,b in zip(indices, indices[1:])]
            return Counter(gaps).most_common(1)[0][1] / len(gaps) if gaps else 0
        choices.append((regular(rows)+regular(cols), -(len(rows)+len(cols)), color, rows, cols))
    _, _, line, rows, cols = max(choices, key=lambda x:(x[0], -len(x[3])-len(x[4])))
    bg = Counter(grid[r][c] for r in range(h) if r not in rows for c in range(w) if c not in cols).most_common(1)[0][0]
    # At each divider intersection, the color belongs to the lattice cell
    # diagonally opposite it (up-left), with edge positions clamped.
    result = [[bg for _ in range(len(cols)-1)] for _ in range(len(rows)-1)]
    for i,r in enumerate(rows):
        for j,c in enumerate(cols):
            value=grid[r][c]
            if value==line or value==bg:
                continue
            oi=max(0,i-1); oj=max(0,j-1)
            if oi<len(result) and oj<len(result[0]):
                result[oi][oj]=value
    return result
