 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    options = []
    for color in set(v for row in grid for v in row):
        rows = [r for r, row in enumerate(grid) if row.count(color) >= 0.70 * w]
        cols = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= 0.70 * h]
        if len(rows) < 2 or len(cols) < 2:
            continue
        def regular(indices):
            gaps = [b-a for a,b in zip(indices,indices[1:])]
            return Counter(gaps).most_common(1)[0][1] / len(gaps) if gaps else 0
        options.append((regular(rows)+regular(cols),-(len(rows)+len(cols)),color,rows,cols))
    _,_,line,rows,cols=max(options,key=lambda x:(x[0],x[1]))
    rowset,colset=set(rows),set(cols)
    background=Counter(grid[r][c] for r in range(h) if r not in rowset for c in range(w) if c not in colset).most_common(1)[0][0]
    # Every output tile takes the marker found at its lower-right junction;
    # absent markers leave the background value.
    out=[]
    for i in range(len(rows)-1):
        row=[]
        for j in range(len(cols)-1):
            value=grid[rows[i+1]][cols[j+1]]
            row.append(value if value not in (line,background) else background)
        out.append(row)
    return out
