 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    options = []
    for color in set(v for row in grid for v in row):
        rows = [r for r,row in enumerate(grid) if row.count(color) >= .70*w]
        cols = [c for c in range(w) if sum(grid[r][c] == color for r in range(h)) >= .70*h]
        if len(rows) < 2 or len(cols) < 2: continue
        def periodic(xs):
            ds=[b-a for a,b in zip(xs,xs[1:])]
            return Counter(ds).most_common(1)[0][1]/len(ds) if ds else 0
        options.append((periodic(rows)+periodic(cols),-(len(rows)+len(cols)),color,rows,cols))
    _,_,line,rows,cols=max(options,key=lambda q:(q[0],q[1]))
    rowset,colset=set(rows),set(cols)
    bg=Counter(grid[r][c] for r in range(h) if r not in rowset for c in range(w) if c not in colset).most_common(1)[0][0]
    nr,nc=len(rows)-1,len(cols)-1
    out=[[bg for _ in range(nc)] for _ in range(nr)]
    # A marker at any of a tile's four corner junctions paints that tile.
    for i in range(len(rows)):
        for j in range(len(cols)):
            val=grid[rows[i]][cols[j]]
            if val in (line,bg): continue
            for oi in (i-1,i):
                for oj in (j-1,j):
                    if 0<=oi<nr and 0<=oj<nc:
                        out[oi][oj]=val
    return out
